def multiply(mat1, mat2):
    m = len(mat1)
    n = len(mat2[0])
    answer = []
    for i in range(m):
        t = []
        for r in range(n):
            tmp = 0
            for j in range(len(mat1[0])):
                tmp += mat1[i][j] * mat2[j][r]
            t.append(tmp)
        answer.append(t)
    return answer

def union_array(nums1, nums2):
    for i in range(len(nums1)-1, -1, -1):
        if nums1[i] == 0:
            nums1.pop(i)
        else:
            break
    for i in range(len(nums2)-1, -1, -1):
        if nums2[i] == 0:
            nums2.pop(i)
        else:
            break
    n1 = len(nums1)
    n2 = len(nums2)
    i = 0
    j = 0
    while i < n1 and j < n2:
        if i < n1 and nums1[i] <= nums2[j]:
            i += 1
        if j < n2 and nums1[i] > nums2[j]:
            nums1.insert(i, nums2[j])
            i += 1
            j += 1
    if j < n2:
        nums1.extend(nums2[j:])
    return nums1

def remove_failing_students(grades):
    passing_grades = {name: grade for name, grade in grades if grade >= 60}
    return passing_grades

def find_longest_zeros(number):
    binary_str = bin(number)[2:] 
    max_gap = 0
    current_gap = 0

    for bit in binary_str:
        if bit == '0':
            current_gap += 1
        elif bit == '1':
            if current_gap > max_gap:
                max_gap = current_gap
            current_gap = 0

    return max_gap

import math

def sum_of_digit_factorials(n):
    return sum(math.factorial(int(digit)) for digit in str(n))

from collections import Counter

def most_frequent_numbers(numbers):
    cont = Counter(numbers)
    sorted_d = sorted(cont.items(), key=lambda x:x[1])
    max_count = sorted_d[-1][-1]
    ans = []
    for val,count in sorted_d:
        if count == max_count:
            ans.append(val)
    return ans

def find_perfect_numbers(start, end):
    def is_perfect(n):
        sum = 1
        i = 2
        while i <= n/i:
            if n % i == 0:
                sum += i+int(n/i)
            i+=2
        if i*i == n:
            sum -= i
        return sum == n and n!=1

    perfect_numbers = []
    for num in range(start, end+1):
        if is_perfect(num):
            perfect_numbers.append(num)
    return perfect_numbers

def count_set_bits(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def length_LongestSubstring(s: str) -> int:
    char_map = {}
    left = 0
    max_length = 0

    for right in range(len(s)):
        if s[right] in char_map:
            left = max(left, char_map[s[right]] + 1)
        char_map[s[right]] = right
        max_length = max(max_length, right - left + 1)

    return max_length

def second_largest_digit(s):
    digits = [int(c) for c in s if c.isdigit()]
    digits = list(set(digits))
    digits.sort()
    if len(digits) < 2:
        return -1
    else:
        return digits[-2]

def findCombinations(nums, k):
    if len(nums) < k:
        return []
    if len(nums) == k:
        return [nums]
    if k == 1:
        return [[x] for x in nums]
    res = []
    for i in range(len(nums)):
        for subset in findCombinations(nums[i+1:], k-1):
            res.append([nums[i]] + subset)
    return res

from functools import lru_cache

def count_pattern_as_subsequence(text: str, pattern: str) -> int:
    len_text = len(text)
    len_pattern = len(pattern)

    @lru_cache(maxsize=None)
    def dp(i, j):
        if j == len_pattern:
            return 1
        if i == len_text:
            return 0
        if text[i] == pattern[j]:
            return dp(i + 1, j + 1) + dp(i + 1, j)
        else:
            return dp(i + 1, j)

    return dp(0, 0)

def convert_signs(nums):
    result = []
    for num in nums:
        if num > 0:
            result.append(1)
        elif num < 0:
            result.append(-1)
        else:
            result.append(0)
    return result

def min_changes_alternating(s):
    count1 = 0
    count2 = 0
    for i in range(len(s)):
        if i % 2 == 0:
            if s[i] != '1':
                count1 += 1
            else:
